const indexes = { de: 1, fr: 2, es: 3 } as const;
const exactRows = new Map(rows.map(row => [row[0], row]));
export const additionalTranslationKeys = rows.map(row => row[0]);
const templateRows = rows.filter(row => row[0].includes("{value}"))
  .sort((a, b) => b[0].replace(/\{[^}]+\}/g, "").length - a[0].replace(/\{[^}]+\}/g, "").length)
  .map(row => {
  const keys: string[] = [];
  const escaped = row[0].split(/(\{(?:value|detail)\})/).map(part => {
    if (/^\{(?:value|detail)\}$/.test(part)) {
      keys.push(part);
      return "(.+?)";
    }
    return part.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }).join("");
  return { row, keys, pattern: new RegExp(`^${escaped}$`, "s") };
});

export function translateAdditional(
  locale: Exclude<Locale, "en" | "ru" | "it" | "pl">,
  text: string,
  translatePart: (text: string) => string,
): string | undefined {
  const exact = exactRows.get(text);
  if (exact) return exact[indexes[locale]];
  const sentences = text.split(/(?<=[.!?])\s+(?=[A-Z0-9])/);
  if (sentences.length > 1) {
    const translated = sentences.map(translatePart);
    if (translated.some((sentence, index) => sentence !== sentences[index])) return translated.join(" ");
  }
  for (const { row, keys, pattern } of templateRows) {
    const match = text.match(pattern);
    if (match) {
      return row[indexes[locale]].replace(/\{(?:value|detail)\}/g, key =>
        translatePart(match[keys.indexOf(key) + 1]),
      );
    }
  }
  const productList = text.split(/ and (?=Microsoft |a SharePoint )/);
  if (productList.length > 1) {
    return productList.map(translatePart).join(locale === "de" ? " und " : locale === "fr" ? " et " : " y ");
  }
  for (const separator of [" + ", ", "]) {
    const parts = text.split(separator);
    if (parts.length > 1) {
      const translated = parts.map(translatePart);
      if (translated.some((part, index) => part !== parts[index])) return translated.join(separator);
    }
  }
  return undefined;
}
